// 1. Recupera os clientes do nó Webhook
const webhookData = $('Webhook').first().json;
const clientes = (webhookData.body && webhookData.body.clientes) 
  ? webhookData.body.clientes 
  : (webhookData.clientes || []);

// 2. Recupera o texto do CSV vindo do HTTP Request
const httpData = $input.first().json;
const csvTexto = typeof httpData === 'string' 
  ? httpData 
  : (httpData.data || Object.values(httpData)[0] || '');

// 3. Converte o CSV em uma lista de objetos
const linhas = csvTexto.trim().split('\n').slice(1); // remove o cabeçalho
const investimentos = linhas.map(linha => {
  const [perfil, produto, minimo, rentabilidade] = linha.split(',');
  return { 
    perfil: perfil?.trim(), 
    produto: produto?.trim(), 
    minimo: minimo?.trim(), 
    rentabilidade: rentabilidade?.trim() 
  };
});

// 4. Cruza cada cliente com o seu perfil e monta a mensagem
const resultados = clientes.map(cliente => {
  // Filtra apenas os investimentos compatíveis com o perfil do cliente
  const recomendados = investimentos.filter(inv => 
    inv.perfil && cliente.perfil && inv.perfil.toLowerCase() === cliente.perfil.toLowerCase()
  );

  // Formata os produtos em tópicos
  const listaProdutos = recomendados.map(inv => 
    `• ${inv.produto} (Mínimo: R$ ${inv.minimo} | Rentabilidade: ${inv.rentabilidade})`
  ).join('\n');

  // Monta a mensagem final personalizada
  const mensagem = `Olá, ${cliente.nome}!\n\n` +
    `Analisamos sua conta com saldo de ${cliente.saldo} e perfil ${cliente.perfil}.\n` +
    `Recomendamos as seguintes opções de investimento para você:\n\n` +
    `${listaProdutos}\n\n` +
    `Conte com a nossa assessoria para investir com segurança!`;

  return {
    json: {
      nome: cliente.nome,
      email: cliente.email,
      perfil: cliente.perfil,
      saldo: cliente.saldo,
      investimentos: recomendados,
      mensagemFinal: mensagem
    }
  };
});

return resultados;

// 1. Função auxiliar para sortear uma mensagem da lista
function pick(lista) {
  if (!lista || lista.length === 0) return '';
  const indice = Math.floor(Math.random() * lista.length);
  return lista[indice];
}

// 2. Função auxiliar para converter "R$ 12.500,00" em número (12500)
function parseSaldo(saldoTexto) {
  if (typeof saldoTexto === 'number') return saldoTexto;
  if (!saldoTexto) return 0;
  const limpo = saldoTexto.toString()
    .replace(/R\$\s?/g, '')
    .replace(/\./g, '')
    .replace(',', '.')
    .trim();
  return parseFloat(limpo) || 0;
}

// 3. Obtém todos os itens que chegaram ao nó
const itens = $input.all();

// 4. Mapeia e enriquece cada cliente
const resultados = itens.map(item => {
  const c = item.json;
  const nome = c.nome || 'Cliente';
  const email = c.email || '';
  const perfil = c.perfil || 'Conservador';
  const saldoTexto = c.saldo || 'R$ 0,00';
  const saldoNum = parseSaldo(saldoTexto);
  const investimentos = c.investimentos || [];

  // Filtra opções que o saldo do cliente consegue cobrir (saldo >= minimo)
  const acessiveis = investimentos.filter(inv => {
    const minVal = parseFloat(inv.minimo) || 0;
    return saldoNum >= minVal;
  });

  // Escolhe o investimento acessível mais rentável (ou o primeiro da lista)
  const escolhido = acessiveis.length > 0 ? acessiveis[0] : (investimentos[0] || {
    produto: 'Reserva de Emergência',
    minimo: '0',
    rentabilidade: '100% CDI'
  });

  // Cria a justificativa da recomendação baseada no perfil
  let motivo = '';
  const perfilLower = perfil.toLowerCase();
  if (perfilLower === 'conservador') {
    motivo = `Produto de baixo risco com rentabilidade de ${escolhido.rentabilidade}, ideal para preservar seu patrimônio.`;
  } else if (perfilLower === 'moderado') {
    motivo = `Equilíbrio ideal entre rentabilidade (${escolhido.rentabilidade}) e segurança, aproveitando seu saldo de ${saldoTexto}.`;
  } else {
    motivo = `Potencial de alta valorização no longo prazo (${escolhido.rentabilidade}), alinhado à sua estratégia de crescimento de capital.`;
  }

  // Gera 3 variações de mensagens para humanizar o contato
  const mensagens = [
    `Olá, ${nome}! Com base no seu perfil ${perfil} e saldo disponível de ${saldoTexto}, nossa recomendação principal é o ${escolhido.produto}. ${motivo}`,
    `Prezado(a) ${nome}, identificamos uma oportunidade exclusiva para o perfil ${perfil}: investir em ${escolhido.produto} (${escolhido.rentabilidade}). ${motivo}`,
    `Oi, ${nome}! Que tal fazer seu saldo de ${saldoTexto} render mais? Para o seu perfil ${perfil}, a melhor indicação de hoje é ${escolhido.produto}. ${motivo}`
  ];

  return {
    nome,
    email,
    perfil,
    saldo_texto: saldoTexto,
    saldo_num: saldoNum,
    recomendacao: escolhido,
    motivo,
    mensagens,
    mensagem_escolhida: pick(mensagens)
  };
});

// 5. Retorna no formato padrão que o n8n espera
return resultados.map(r => ({ json: r }));

const resultados = $json.resultados || [];

function parseBRL(valor) {
  if (valor == null || valor === "") return 0;

  const s = String(valor)
    .replace(/R\$\s?/g, "")
    .replace(/\./g, "")
    .replace(",", ".")
    .trim();

  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

// Retorna UM ITEM por cliente
const out = resultados.map(c => {
  const saldoNum =
    c.saldo_num ?? parseBRL(c.saldo_texto ?? c.saldo);

  return {
    json: {
      email_to: String(c.email || "").trim(),
      nome: String(c.nome || "").trim(),
      perfil: c.perfil,
      saldo_texto: c.saldo_texto ?? c.saldo,
      saldo_num: saldoNum,
      recomendacao: c.recomendacao,
      motivo: c.motivo,
      mensagem_base:
        c.mensagem_escolhida || c.mensagens?.[0] || "",
      copy_rules: {
        idioma: "pt-BR",
        tom: "amigável e profissional",
        tamanho: "curto (4-6 linhas)",
        evitar: [
          "promessas de ganho",
          "garantias",
          "linguagem agressiva"
        ]
      }
    }
  };
});

return out;

