// Recupera todos os itens recebidos
const items = $input.all();

return items.map(item => {
  // 'j' representa o objeto com os dados do cliente e da recomendação
  const j = item.json;

  // Pega o texto gerado pela IA (Gemini costuma gravar em 'text' ou 'content')
  // Se a IA não tiver rodado, usa a 'mensagem_escolhida' como fallback
  const textoIA = j.text || j.content || j.mensagem_escolhida || j.mensagemFinal || '';

  const nome = j.nome || 'Cliente';
  const email = j.email || '';
  const perfil = j.perfil || 'Não informado';
  const saldo = j.saldo_texto || j.saldo || 'R$ 0,00';
  const produto = j.recomendacao?.produto || 'Produto Recomendado';
  const rentabilidade = j.recomendacao?.rentabilidade || 'A consultar';
  const minimo = j.recomendacao?.minimo ? `R$ ${j.recomendacao.minimo}` : 'Sem mínimo';
  const motivo = j.motivo || 'Alinhado à sua estratégia de investimento.';

  // 1. Destinatário
  const to = email;

  // 2. Assunto do E-mail
  const subject = `🎯 ${nome}, sua recomendação exclusiva de investimentos (${perfil})`;

  // 3. Versão em Texto Puro
  const text_body = `${textoIA}\n\n---\nResumo da Oportunidade:\n• Produto: ${produto}\n• Rentabilidade: ${rentabilidade}\n• Mínimo: ${minimo}\n• Perfil: ${perfil}\n• Saldo Considerado: ${saldo}\n\nMotivo: ${motivo}`;

  // 4. Versão em HTML estilizado para envio de E-mail
  const html_body = `
    <div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; color: #333; line-height: 1.6; border: 1px solid #e2e8f0; border-radius: 8px; overflow: hidden;">
      <div style="background: linear-gradient(135deg, #1e3a8a, #3b82f6); color: white; padding: 24px; text-align: center;">
        <h1 style="margin: 0; font-size: 20px;">Assistente de Investimentos</h1>
        <p style="margin: 6px 0 0; font-size: 13px; opacity: 0.9;">Recomendação inteligente e personalizada</p>
      </div>

      <div style="padding: 24px;">
        <p style="white-space: pre-line; font-size: 15px; color: #1e293b;">${textoIA}</p>

        <div style="background-color: #f8fafc; border-left: 4px solid #3b82f6; padding: 16px; margin: 20px 0; border-radius: 4px;">
          <h3 style="margin-top: 0; color: #1e3a8a; font-size: 15px;">📊 Resumo da Oportunidade</h3>
          <ul style="padding-left: 20px; margin: 0; font-size: 14px;">
            <li><strong>Produto Indicado:</strong> ${produto}</li>
            <li><strong>Rentabilidade Estimada:</strong> ${rentabilidade}</li>
            <li><strong>Aplicação Mínima:</strong> ${minimo}</li>
            <li><strong>Perfil de Risco:</strong> ${perfil}</li>
            <li><strong>Saldo Disponível:</strong> ${saldo}</li>
          </ul>
        </div>

        <p style="font-size: 13px; color: #64748b; font-style: italic; margin-bottom: 0;">
          <strong>Justificativa da Assessoria:</strong> ${motivo}
        </p>
      </div>

      <div style="background-color: #f1f5f9; padding: 14px; text-align: center; font-size: 12px; color: #94a3b8; border-top: 1px solid #e2e8f0;">
        Mensagem gerada automaticamente pelo Assistente de Investimentos RPA com IA.
      </div>
    </div>
  `;

  // 5. Retorno no padrão da aula para debug e disparo
  return {
    json: {
      ok: true,
      to,
      subject,
      text_body,
      html_body,

      // (opcional) manter alguns campos úteis pra debug/aula
      meta: {
        nome: j.nome,
        perfil: j.perfil,
        produto: j.recomendacao?.produto,
        minimo: j.recomendacao?.minimo,
        rentabilidade: j.recomendacao?.rentabilidade,
        motivo: j.motivo
      }
    }
  };
});
